    over_four_hours = 0
    for plate, minutes in stays:
        hours = (minutes + 59) // 60
        if permit == 'visitor':
            fees_cents += 225 * hours
        elif permit == 'resident':
            fees_cents += (225 * hours + 1) // 2
        if minutes > 240:
            over_four_hours += 1

    longest_plate = ''
    longest_minutes = -1
    for plate, minutes in stays:
