def solve(inputs, readings):
    def to_cents(amount):
        whole, fraction = amount.strip().split(".")
        return int(whole) * 100 + int(fraction.ljust(2, "0")[:2])

    def show_cents(cents):
        return "{}.{:02d}".format(cents // 100, cents % 100)

    payments = []
    for line in inputs["payments"].splitlines():
        name, amount = line.split("|", 1)
        payments.append((name.strip(), to_cents(amount)))

    total = sum(amount for name, amount in payments)
    split = readings["split"]

    if split == "equal":
        denominator = len(payments)
        shares = [(2 * total + denominator) // (2 * denominator) for name, amount in payments]
    else:
        weights = inputs["weights"]
        denominator = sum(weights[name] for name, amount in payments)
        shares = [(2 * total * weights[name] + denominator) // (2 * denominator) for name, amount in payments]

    balances = [amount - share for (name, amount), share in zip(payments, shares)]
    owed_index = max(range(len(payments)), key=lambda i: balances[i])
    owing_index = min(range(len(payments)), key=lambda i: balances[i])
    owed_name = payments[owed_index][0]
    owing_name = payments[owing_index][0]

    return "{} | total {} | most owed {} {} | most owing {} {}".format(
        split,
        show_cents(total),
        owed_name,
        show_cents(abs(balances[owed_index])),
        owing_name,
        show_cents(abs(balances[owing_index]))
    )

import re

def solve(inputs, readings):
    pages = inputs["pages"]
    if isinstance(pages, str):
        pages = {
            match.group(1): [int(value) for value in re.findall(r"-?\d+", match.group(2))]
            for match in re.finditer(r'"((?:\\.|[^"\\])*)"\s*:\s*\[([^\]]*)\]', pages)
        }

    genre = readings["genre"]
    targets = {"mystery": 300, "romance": 250, "history": 400, "science": 350}
    totals = {name: sum(weekly_pages) for name, weekly_pages in pages.items()}
    count = len(totals)
    met = sum(total >= targets[genre] for total in totals.values())
    average = (2 * sum(totals.values()) + count) // (2 * count) if count else 0
    top = min(totals, key=lambda name: (-totals[name], name)) if totals else ""
    return f"{genre}: {met} of {count} met target, average {average} pages, top {top}"
